CREATE TABLE public.customer_sale_places (
	id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
	customer_id integer REFERENCES public.customers(id) ON DELETE RESTRICT ON UPDATE CASCADE,
	name text NOT NULL,
	address text,
	is_active boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE public.customer_sale_places IS 'Customer sale place reference data.';
COMMENT ON COLUMN public.customer_sale_places.customer_id IS 'Customer reference';
COMMENT ON COLUMN public.customer_sale_places.name IS 'Customer sale place display name.';
COMMENT ON COLUMN public.customer_sale_places.address IS 'Sale place optional exact address.';
COMMENT ON COLUMN public.customer_sale_places.is_active IS 'Whether the sale place is active.';

CREATE UNIQUE INDEX customer_sale_places_customer_name_idx
	ON public.customer_sale_places USING btree (customer_id, lower(name));

WITH required(code, description) AS (
	VALUES
		('customerSalePlace.create', 'Create Customer sale place'),
		('customerSalePlace.list', 'Просмотр списка точек продаж'),
		('customerSalePlace.detail', 'Просмотр точки продажи'),
		('customerSalePlace.update', 'Изменение точки продажи'),
		('customerSalePlace.delete', 'Удаление точки продажи')
)
INSERT INTO public.permissions (code, description)
SELECT required.code, required.description
FROM required
ON CONFLICT (code) DO UPDATE
SET description = EXCLUDED.description;

WITH roles(role_id) AS (
	VALUES
		('admin'::public.role_types)
), required(permission_code) AS (
	VALUES
		('customerSalePlace.create'),
		('customerSalePlace.list'),
		('customerSalePlace.detail'),
		('customerSalePlace.update'),
		('customerSalePlace.delete')
)
INSERT INTO public.role_permissions (role_id, permission_code)
SELECT roles.role_id, required.permission_code
FROM roles
CROSS JOIN required
ON CONFLICT DO NOTHING;

